Here is the root cause:
The loop in vfe_isr() incorrectly used MSM_VFE_IMAGE_MASTERS_NUM (7) as the bound for iterating and calling vfe_isr_reg_update() with the loop index, but vfe->line[] array is defined with size VFE_LINE_NUM_MAX (4). This causes out‑of‑bounds memory access when the index is 4, 5, or 6, as those indices exceed the array boundaries.

Here is the patch:
  */
 static irqreturn_t vfe_isr(int irq, void *dev)
 {
 	struct vfe_device *vfe = dev;
 	u32 status;
 	int i;

 	status = readl_relaxed(vfe->base + VFE_IRQ_STATUS(0));
 	writel_relaxed(status, vfe->base + VFE_IRQ_CLEAR(0));
 	writel_relaxed(IRQ_CMD_GLOBAL_CLEAR, vfe->base + VFE_IRQ_CMD);

 	if (status & IRQ_MASK_0_RESET_ACK)
 		vfe_isr_reset_ack(vfe);

 	if (status & IRQ_MASK_0_BUS_TOP_IRQ) {
 		u32 status = readl_relaxed(vfe->base + VFE_BUS_IRQ_STATUS(0));

 		writel_relaxed(status, vfe->base + VFE_BUS_IRQ_CLEAR(0));
 		writel_relaxed(1, vfe->base + VFE_BUS_IRQ_CLEAR_GLOBAL);

-		/* Loop through all WMs IRQs */
-		for (i = 0; i < MSM_VFE_IMAGE_MASTERS_NUM; i++) {
+		for (i = 0; i < MAX_VFE_OUTPUT_LINES; i++) {
 			if (status & BUS_IRQ_MASK_0_RDI_RUP(vfe, i))
 				vfe_isr_reg_update(vfe, i);
+		}

+		/* Loop through all WMs IRQs */
+		for (i = 0; i < MSM_VFE_IMAGE_MASTERS_NUM; i++) {
 			if (status & BUS_IRQ_MASK_0_COMP_DONE(vfe, RDI_COMP_GROUP(i)))
 				vfe_buf_done(vfe, i);
 		}
 	}

 	return IRQ_HANDLED;
 }



